 app.undoPrompt();if(str(wirePromptDrafts(store->state),"character_prompt")!="yellow eyes")throw std::runtime_error("Cross-field undo failed");app.undoPrompt(true);if(str(wirePromptDrafts(store->state),"character_prompt")!="blue hair")throw std::runtime_error("Cross-field redo failed");
 for(int i=0;i<10;i++){show(1);type(L"character "+std::to_wstring(i));show(0);if(str(wirePromptDrafts(store->state),"scene_prompt")!="library")throw std::runtime_error("Round-trip changed another field");}
 auto valid=promptSnapshot(store->state);type(L"[char]broken");if(str(store->state,"_prompt_error").empty()||str(store->state["drafts"],"prompt")!="[char]broken")throw std::runtime_error("Invalid source was lost or silently accepted");bool blocked=false;try{generationForm(store->settings,store->state,"fixture");}catch(...){blocked=true;}if(!blocked)throw std::runtime_error("Invalid source reached request serialization");
