 store->save();Store restarted(folder/"state");restarted.load();if(restarted.state["drafts"]!=store->state["drafts"])throw std::runtime_error("Restart lost linked fields");
 if(restarted.state.value("_prompt_legacy_backup",json())!=before)throw std::runtime_error("Legacy rollback backup was lost or overwritten");auto exported=legacyPromptExport(store->state);if(exported.contains("_prompt_legacy_backup")||str(exported["drafts"],"prompt").find("[free]")!=std::string::npos)throw std::runtime_error("Legacy export leaked history or markup");auto restored=store->state;restorePromptSnapshot(restored,restored["_prompt_legacy_backup"]);if(promptSnapshot(restored)!=before)throw std::runtime_error("Persistent legacy rollback failed");
